"""build_result_gate_doc.py — renders the tables embedded in docs/RESULT_dl_monthly_gate_2026-09-05.md
from the ARCHIVED products only (results/judge_gate.json, results/score_{mE1,mE60}.json, results/decisions_{mE1,mE60}.json).
Every number in the RESULT doc's tables comes from this script's output (gate_tables.md). No pod access, no arrays.
Unit chain (E-0904-G, printed, not hand-computed): g = net_ex/gross_total in bps per anchor per unit gross;
%/gross/yr = mean_g * 2190 / 100; NAV %/yr at L=2x = mean_g * 2190 * 2 / 1e4 * 100 = mean_g * 43.8; 2xDD %NAV = maxDD_bps_gross * 2 / 100.
usage: python3 build_result_gate_doc.py <archive_dir>  → <archive_dir>/gate_tables.md + stdout"""
import sys, os, json
A = sys.argv[1] if len(sys.argv) > 1 else os.path.dirname(os.path.abspath(__file__))
J = json.load(open(f"{A}/results/judge_gate.json"))
SC = {T: json.load(open(f"{A}/results/score_{T}.json")) for T in ("mE1", "mE60")}
DC = {T: json.load(open(f"{A}/results/decisions_{T}.json")) for T in ("mE1", "mE60")}
PW = "2025-03->26<=cut"; W26 = "2026<=cut"; W25 = "2025-03->12"; W0102 = "2025-01/02"
L = J["levels"]; D = J["deltas"]; JU = J["judge"]; out = []
def p(s=""): out.append(s); print(s)
def ci(b): return f"{b['mean']:+.3f} [{b['lo']:+.3f}, {b['hi']:+.3f}]"
def dcell(name, w=PW):
    d = D.get(name); return ci(d["windows"][w]) if d and w in d["windows"] else "n/a"
p(f"<!-- generated by build_result_gate_doc.py from {os.path.basename(A)}/results/*.json; n_anchors={J['n_anchors']} {J['first']}→{J['last']}; cut={J['cut']}; windows={J['windows']}; bootstrap={J['bootstrap']} -->")
p("## A · Arm table — primary window 2025-03-01→2026-08-10 20Z (n=3168 anchors, same set for all arms); per-gross caliber g = net_ex/gross_total (bps/anchor/unit gross); Δ = paired by anchor, UTC-day-block bootstrap 2000, seed 20260905, CI95")
p("| arm | role | swaps | mean age (2025-03→) | max age | IC primary ± se | g primary | %/gross/yr | NAV %/yr @2× | Sharpe | maxDD bps (2×DD %NAV) | turn/gross | g 2026≤cut (S) | g 2025-03→12 (S) | Δ vs R0(mE1) | Δ vs yearly s42 | Δ vs yearly s2027 |")
p("|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|")
ROLE = {"BASE_s42": "R-yearly (09-01 gate model, seed 42)", "BASE_s2027": "R-yearly seed 2027", "G_mE1_R0": "R0 = live form (monthly refit, E1, age 1)", "G_mE1_R1": "R1 gate-IC (E1)", "G_mE1_R2": "R2 gate-leg (E1)", "G_mE1_R3": "R3 both (E1)", "G_mE1_R4": "R4 absolute IC>0 (E1)",
        "G_mE60_R0": "R0 (E60 cutoff)", "G_mE60_R1": "R1 (E60)", "G_mE60_R2": "R2 (E60)", "G_mE60_R3": "R3 (E60)", "G_mE60_R4": "R4 (E60)", "G_mE1_R1_phidyn": "R1 + φdyn [0.30,0.60] (§A3)", "G_mE1_R0_phidyn": "R0 + φdyn (aux)"}
for k, row in L.items():
    pr = row[PW]; ic = row.get("ic_primary"); sw = row.get("swaps"); ma = row.get("mean_age"); mx = row.get("max_age")
    dR0 = dcell(f"{k} − R0(mE1)") if k != "G_mE1_R0" else "(ref)"
    dY42 = dcell(f"{k} − yearly s42") if not k.startswith("BASE") else ("(ref)" if k == "BASE_s42" else "n/a")
    if k == "G_mE1_R0": dY42 = dcell("R0(mE1) − yearly s42 [§A4 keepable]")
    dY27 = dcell(f"{k} − yearly s2027") if not k.startswith("BASE") else ("(ref)" if k == "BASE_s2027" else "n/a")
    if k == "G_mE1_R0": dY27 = dcell("R0(mE1) − yearly s2027")
    p(f"| {k} | {ROLE.get(k, k)} | {sw if sw is not None else '-'} | {(f'{ma:.2f}' if isinstance(ma, (int, float)) else '-')} | {mx if mx is not None else '-'} | "
      + (f"{ic['mean']:+.4f} ± {ic['se_anchor']:.4f}" if ic else "-") + f" | **{pr['mean']:+.3f}** [{pr['boot']['lo']:+.3f}, {pr['boot']['hi']:+.3f}] | {pr['pct_gross_yr']:+.1f}% | {pr['mean']*43.8:+.1f}% | {pr['sharpe']:+.2f} | {pr['maxDD_bps']:.0f} ({pr['maxDD_bps']*2/100:.1f}%) | {pr['turn_per_gross']:.5f} | "
      + f"{row[W26]['mean']:+.3f} ({row[W26]['sharpe']:+.2f}) | {row[W25]['mean']:+.3f} ({row[W25]['sharpe']:+.2f}) | {dR0} | {dY42} | {dY27} |")
p()
p("## B · Paired Δ detail (primary window unless stated): Δ [CI95] P(Δ>0) · ΔSharpe · Δturn% · maxDD ref→x · months with Δ>0 · best month share · Δ without best month")
p("| pair | 2025-01/02 | 2025-03→12 | 2026≤cut | **primary 2025-03→26≤cut** | ΔSharpe | Δturn% | maxDD ref→x | months + | best month (share of total) | Δ w/o best month |")
p("|---|---|---|---|---|---|---|---|---|---|---|")
for name, d in D.items():
    w = d["windows"]; f = lambda k: (f"{w[k]['mean']:+.3f} [{w[k]['lo']:+.3f},{w[k]['hi']:+.3f}] P{w[k]['P>0']:.2f}" if k in w else "n/a")
    bm = d["best_month"]; share = d["best_month_share"]
    p(f"| {name} | {f(W0102)} | {f(W25)} | {f(W26)} | **{f(PW)}** | {d['dSharpe'][PW]:+.3f} | {d['dturn_pct_primary']:+.1f}% | {d['maxDD_ref']:.0f}→{d['maxDD_x']:.0f} | {d['n_months_pos']}/{d['n_months']} | {bm} {d['monthly_contrib'][bm]['sum_bps']:+.0f} bps ({(share*100 if share is not None else float('nan')):+.0f}%) | {ci(d['drop_best_month'])} |")
p()
p("## C · Frozen judge §A4 (verbatim from results/judge_gate.json['judge'])")
p("```json"); p(json.dumps(JU, indent=1, ensure_ascii=False)); p("```")
p()
p("## D · Reconciliation of the 'keepable' reading with RESULT_dl_monthly_walkforward (f311321; window 2025-01-01→cut, n=3522): anchor-weighted combination of the two sub-windows (INFERRED arithmetic from VERIFIED cells)")
for name in ("R0(mE1) − yearly s42 [§A4 keepable]", "R0(mE1) − yearly s2027"):
    d = D[name]; a = d["windows"][W0102]; b = d["windows"][PW]; n1, n2 = a["n"], b["n"]; comb = (n1 * a["mean"] + n2 * b["mean"]) / (n1 + n2)
    p(f"- {name}: 2025-01/02 (n={n1}) {a['mean']:+.4f} [{a['lo']:+.3f},{a['hi']:+.3f}]; primary (n={n2}) {b['mean']:+.4f} [{b['lo']:+.3f},{b['hi']:+.3f}]; anchor-weighted 2025-01→cut (n={n1+n2}) = **{comb:+.4f}** bps/anchor/gross (= {comb*43.8:+.2f} NAV %/yr @2×); primary-window Δ = {b['mean']*43.8:+.2f} NAV %/yr @2×")
p()
p("## E · Score level (per-anchor rank IC vs y4s over members; primary window; day-block bootstrap for Δ)")
for T in ("mE1", "mE60"):
    s = SC[T]; p(f"### {T}"); p("| arm | IC primary | se | ΔIC vs R0 [CI95] | ΔIC vs yearly [CI95] |"); p("|---|---|---|---|---|")
    for r in ("R0", "R1", "R2", "R3", "R4", "yearly"):
        lv = s["ic_levels"].get(f"{PW}/{r}"); d0 = s["ic_delta"].get(f"{PW}/{r}-R0"); dy = s["ic_delta"].get(f"{PW}/{r}-yearly")
        fmt = lambda b: (f"{b['mean']:+.4f} [{b['ci95'][0]:+.4f},{b['ci95'][1]:+.4f}]" if b and "mean" in b else "-")
        p(f"| {r} | {lv['mean']:+.4f} | {lv['se_anchor']:.4f} | {fmt(d0)} | {fmt(dy)} |")
    p()
p("## F · Per-month decision table (mE1; VERIFIED results/decisions_mE1.json): deployed model / age / swap; candidate = F(t−1) scored on month t−1 vs incumbent at its age")
p("| month | R0 dep/age | R1 dep/age/swap | R2 | R3 | R4 | IC cand / inc (t−1) | leg cand / inc (t−1, bps) | IC of R1's model this month | IC newest this month |"); p("|---|---|---|---|---|---|---|---|---|---|")
R = DC["mE1"]["rules"]
for i, m in enumerate(DC["mE1"]["months"]):
    r0, r1, r2, r3, r4 = (R[x][i] for x in ("R0", "R1", "R2", "R3", "R4"))
    cmp_ = (f"{r1['ic_cand_tm1']:+.4f} / {r1['ic_inc_tm1']:+.4f} | {r1['leg_cand_tm1']:+.3f} / {r1['leg_inc_tm1']:+.3f}" if r1.get("ic_cand_tm1") is not None else "n/a | n/a")
    p(f"| {m} | {r0['deployed']}/{r0['age']} | {r1['deployed']}/{r1['age']}/{r1['swap']} | {r2['deployed']}/{r2['age']}/{r2['swap']} | {r3['deployed']}/{r3['age']}/{r3['swap']} | {r4['deployed']}/{r4['age']}/{r4['swap']} | {cmp_} | {r1['ic_month']:+.4f} | {r1['ic_newest_month']:+.4f} |")
p()
p("## G · Per-month Δ contribution vs R0(mE1) (sum of Δg over the calendar month, bps gross; primary window) for the arm with CI95 lower > 0 (G_mE1_R4) and the two E1 gate arms R1/R3")
p("| month | G_mE1_R4 | G_mE1_R1 | G_mE1_R3 | G_mE60_R1 |"); p("|---|---|---|---|---|")
names = ["G_mE1_R4 − R0(mE1)", "G_mE1_R1 − R0(mE1)", "G_mE1_R3 − R0(mE1)", "G_mE60_R1 − R0(mE1)"]
for mo in D[names[0]]["monthly_contrib"]:
    p(f"| {mo} | " + " | ".join(f"{D[n]['monthly_contrib'][mo]['sum_bps']:+.1f}" for n in names) + " |")
p("| **total** | " + " | ".join(f"**{D[n]['total_bps']:+.1f}**" for n in names) + " |")
p()
p("## H · φdyn (R1+φdyn, clip [0.30, 0.60], look 900; VERIFIED results/judge_gate.json['phidyn'])")
for k, v in J["phidyn"].items():
    p(f"- {k}: φ mean {v['phi_mean']:.3f} (min {v['phi_min']:.2f}, max {v['phi_max']:.2f}); share at 0.30 {v['share_at_lower_clip']*100:.1f}%, at 0.60 {v['share_at_upper_clip']*100:.1f}%; crossings of 0.45: {v['n_cross_0.45']}; jumps ≥0.05: {v['n_jumps_ge_0.05']}; φ 2025 {v['phi_by_year']['2025']:.3f} / 2026 {v['phi_by_year']['2026']:.3f}")
open(f"{A}/gate_tables.md", "w").write("\n".join(out) + "\n"); print(f"\nwrote {A}/gate_tables.md ({len(out)} lines)")
